# Added print Logic
<#
.SYNOPSIS
    Creates GitHub teams and syncs members and repo permissions from team-mappings.json.

.DESCRIPTION
    This script is config-driven. It reads everything from team-mappings.json:
      1. Creates GitHub teams if they do not exist
      2. Adds maintainers from the 'maintainers' list in config
      3. Adds members from the 'members' list in config
      4. Assigns repository permissions from the 'repositories' list in config

    The team-mappings.json is generated by export-ado-teams.ps1 and reviewed/edited by you.
    No live ADO API calls are made during sync — config is the single source of truth.

.PARAMETER GitHubOrg
    GitHub organization name.

.PARAMETER GitHubPat
    GitHub Personal Access Token with admin:org scope.

.PARAMETER TeamMappingFile
    Path to JSON file containing the team mappings (team-mappings.json).
    This file should be generated by export-ado-teams.ps1 and reviewed before running.
#>

[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [string]$GitHubOrg,

    [Parameter(Mandatory = $true)]
    [string]$GitHubPat,

    [string]$TeamMappingFile = "./config/team-mappings.json"
)

$ErrorActionPreference = "Stop"

# ----------------------------------------------------------
# GitHub Headers
# ----------------------------------------------------------
$ghHeaders = @{
    Authorization          = "Bearer $GitHubPat"
    Accept                 = "application/vnd.github+json"
    "X-GitHub-Api-Version" = "2022-11-28"
}

# ----------------------------------------------------------
# Helper Function - GitHub API
# ----------------------------------------------------------
function Invoke-GitHubApi {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Uri,

        [string]$Method = "GET",

        $Body = $null
    )

    $params = @{
        Uri         = $Uri
        Headers     = $ghHeaders
        Method      = $Method
        ContentType = "application/json"
    }

    if ($null -ne $Body) {
        $params.Body = ($Body | ConvertTo-Json -Depth 5)
    }

    try {
        return Invoke-RestMethod @params
    }
    catch {
        throw $_
    }
}

# ----------------------------------------------------------
# Validate Config File
# ----------------------------------------------------------
if (-not (Test-Path $TeamMappingFile)) {
    Write-Error "Team mapping file not found: $TeamMappingFile"
    Write-Error "Run export-ado-teams.ps1 first to generate the mapping file."
    exit 1
}

# ----------------------------------------------------------
# Load Team Mapping JSON
# ----------------------------------------------------------
Write-Host "Loading team mappings from $TeamMappingFile..." -ForegroundColor Cyan

# Sanitize: Strip // style comments from JSON (not valid JSON, causes parse failures)
$rawJson = Get-Content $TeamMappingFile -Raw
$cleanJson = ($rawJson -split "`n" | Where-Object { $_ -notmatch '^\s*//' }) -join "`n"
try {
    $mappingData = $cleanJson | ConvertFrom-Json
} catch {
    Write-Error "FAILED to parse $TeamMappingFile - invalid JSON. Error: $($_.Exception.Message)"
    Write-Error "Ensure the file contains valid JSON with no // comments."
    exit 1
}
$mappings = $mappingData.mappings

Write-Host "Loaded $($mappings.Count) team mapping(s)." -ForegroundColor Green

# ----------------------------------------------------------
# Audit: Build whitelist of ALL GitHub users from config
# Only these users will receive invitations - no one else.
# ----------------------------------------------------------
$configWhitelist = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
foreach ($m in $mappings) {
    foreach ($u in @($m.maintainers | Where-Object { $_ -and $_.Trim() -ne "" })) { [void]$configWhitelist.Add($u.Trim()) }
    foreach ($u in @($m.members    | Where-Object { $_ -and $_.Trim() -ne "" })) { [void]$configWhitelist.Add($u.Trim()) }
}
Write-Host "`n=== Config Whitelist: Only these $($configWhitelist.Count) GitHub users will be invited ===" -ForegroundColor Cyan
foreach ($wl in ($configWhitelist | Sort-Object)) { Write-Host "  - $wl" -ForegroundColor Gray }
Write-Host "" -ForegroundColor Cyan

# Track all actions for final audit
$auditInvited  = [System.Collections.Generic.List[string]]::new()
$auditSkipped  = [System.Collections.Generic.List[string]]::new()
$auditFailed   = [System.Collections.Generic.List[string]]::new()

Write-Host "=== Starting Team Synchronization (Config-Driven) ===" -ForegroundColor Cyan

# ----------------------------------------------------------
# Process Each Team Mapping
# ----------------------------------------------------------
foreach ($map in $mappings) {

    $githubTeamName = $map.githubTeam

    Write-Host "`n-----------------------------------------" -ForegroundColor DarkGray
    Write-Host "Processing: $($map.adoProject) / $($map.adoTeam) -> $githubTeamName" -ForegroundColor Yellow

    # --------------------------------------------------
    # Step 1 - Ensure GitHub Team Exists
    # --------------------------------------------------
    try {
        $ghTeam = Invoke-GitHubApi -Uri "https://api.github.com/orgs/$GitHubOrg/teams/$githubTeamName"
        Write-Host "  [OK] GitHub team '$githubTeamName' already exists." -ForegroundColor Green

        # --- Update Hierarchy for existing team ---
        if ($map.parentTeam -and $map.parentTeam.Trim() -ne "") {
            $parentName = $map.parentTeam.Trim()
            Write-Host "  Checking/Updating parent for existing team..." -ForegroundColor DarkGray
            
            try {
                $parentTeamObj = Invoke-GitHubApi -Uri "https://api.github.com/orgs/$GitHubOrg/teams/$parentName"
            }
            catch {
                Write-Host "    Creating missing parent '$parentName'..." -ForegroundColor Yellow
                $parentTeamObj = Invoke-GitHubApi -Uri "https://api.github.com/orgs/$GitHubOrg/teams" -Method "POST" -Body @{ name = $parentName; privacy = "closed" }
            }

            Invoke-GitHubApi -Uri "https://api.github.com/orgs/$GitHubOrg/teams/$githubTeamName" -Method "PATCH" -Body @{ parent_team_id = $parentTeamObj.id }
            Write-Host "  [UPDATED] Linked existing team '$githubTeamName' to parent '$parentName'." -ForegroundColor Green
        }
    }
    catch {
        Write-Host "  [NEW] Creating GitHub team '$githubTeamName'..." -ForegroundColor Cyan

        $privacy = if ($map.privacy) { $map.privacy } else { "closed" }
        $createBody = @{
            name        = $githubTeamName
            description = $map.githubTeamDescription
            privacy     = $privacy
        }

        # --- Hierarchy Logic: Handle Parent Team for New Team ---
        if ($map.parentTeam -and $map.parentTeam.Trim() -ne "") {
            $parentName = $map.parentTeam.Trim()
            try {
                $parentTeamObj = Invoke-GitHubApi -Uri "https://api.github.com/orgs/$GitHubOrg/teams/$parentName"
            }
            catch {
                $parentTeamObj = Invoke-GitHubApi -Uri "https://api.github.com/orgs/$GitHubOrg/teams" -Method "POST" -Body @{ name = $parentName; privacy = "closed" }
            }
            $createBody.parent_team_id = $parentTeamObj.id
        }

        $ghTeam = Invoke-GitHubApi -Uri "https://api.github.com/orgs/$GitHubOrg/teams" -Method "POST" -Body $createBody
        Write-Host "  [CREATED] GitHub team '$githubTeamName' with parent." -ForegroundColor Green
    }

    # --------------------------------------------------
    # Step 2 - Add Maintainers
    # --------------------------------------------------
    $maintainerList = @($map.maintainers | Where-Object { $_ -and $_.Trim() -ne "" })
    if ($maintainerList.Count -gt 0) {
        foreach ($ghUser in $maintainerList) {
            # WHITELIST GUARD: Block any user not explicitly in config
            if (-not $configWhitelist.Contains($ghUser.Trim())) {
                Write-Host "    [BLOCKED] $ghUser is NOT in config whitelist - skipping!" -ForegroundColor Red
                $auditSkipped.Add("$ghUser (maintainer in $githubTeamName)")
                continue
            }
            try {
                Invoke-GitHubApi -Uri "https://api.github.com/orgs/$GitHubOrg/teams/$githubTeamName/memberships/$ghUser" -Method "PUT" -Body @{ role = "maintainer" }
                Write-Host "    [MAINTAINER] $ghUser added." -ForegroundColor Green
                $auditInvited.Add("$ghUser (maintainer in $githubTeamName)")
            } catch {
                Write-Warning "    [FAILED] Maintainer: $ghUser - $($_.Exception.Message)"
                $auditFailed.Add("$ghUser (maintainer in $githubTeamName)")
            }
        }
    }

    # --------------------------------------------------
    # Step 3 - Add Members
    # --------------------------------------------------
    $memberList = @($map.members | Where-Object { $_ -and $_.Trim() -ne "" })
    if ($memberList.Count -gt 0) {
        foreach ($ghUser in $memberList) {
            if ($maintainerList -contains $ghUser) { continue }
            # WHITELIST GUARD: Block any user not explicitly in config
            if (-not $configWhitelist.Contains($ghUser.Trim())) {
                Write-Host "    [BLOCKED] $ghUser is NOT in config whitelist - skipping!" -ForegroundColor Red
                $auditSkipped.Add("$ghUser (member in $githubTeamName)")
                continue
            }
            try {
                Invoke-GitHubApi -Uri "https://api.github.com/orgs/$GitHubOrg/teams/$githubTeamName/memberships/$ghUser" -Method "PUT" -Body @{ role = "member" }
                Write-Host "    [MEMBER] $ghUser added." -ForegroundColor Green
                $auditInvited.Add("$ghUser (member in $githubTeamName)")
            } catch {
                Write-Warning "    [FAILED] Member: $ghUser - $($_.Exception.Message)"
                $auditFailed.Add("$ghUser (member in $githubTeamName)")
            }
        }
    }

    # --------------------------------------------------
    # Step 4 - Repo Permissions
    # --------------------------------------------------
    $repoList = @($map.repositories | Where-Object { $_ })
    if ($repoList.Count -gt 0) {
        foreach ($repo in $repoList) {
            try {
                Invoke-GitHubApi -Uri "https://api.github.com/orgs/$GitHubOrg/teams/$githubTeamName/repos/$GitHubOrg/$($repo.name)" -Method "PUT" -Body @{ permission = $repo.permission }
                Write-Host "    [REPO] $($repo.name) -> $($repo.permission)" -ForegroundColor Green
            }
            catch { Write-Warning "    [FAILED] Repo: $($repo.name)" }
        }
    }
}

# ----------------------------------------------------------
# Final Audit Summary
# ----------------------------------------------------------
Write-Host "`n=========================================" -ForegroundColor Cyan
Write-Host " Team Synchronization Complete" -ForegroundColor Cyan
Write-Host "=========================================" -ForegroundColor Cyan
Write-Host " Users Invited/Updated : $($auditInvited.Count)" -ForegroundColor Green
if ($auditInvited.Count -gt 0) {
    foreach ($i in $auditInvited) { Write-Host "   - $i" -ForegroundColor Gray }
}
if ($auditSkipped.Count -gt 0) {
    Write-Host " Users BLOCKED (not in whitelist) : $($auditSkipped.Count)" -ForegroundColor Red
    foreach ($s in $auditSkipped) { Write-Host "   - $s" -ForegroundColor Red }
}
if ($auditFailed.Count -gt 0) {
    Write-Host " Users FAILED : $($auditFailed.Count)" -ForegroundColor Yellow
    foreach ($f in $auditFailed) { Write-Host "   - $f" -ForegroundColor Yellow }
}
Write-Host "=========================================" -ForegroundColor Cyan